INSERT INTO verses_yousafzai (id, ref, book, chapter, verse, text, text_normalized, testament, translation_key, dialect, audio_r2_key, audio_public_url, created_at, updated_at, tags) VALUES
(23101, 'Mark 1:5', 'Mark', 1, 5, '&nbsp;او د يهوديه د ټول مُلک او د يروشلم اوسېدونکى هغۀ له بهر راووتل، هغۀ هغوئ له د خپلو ګناهونو په اقرار کولو سره د اُردن د سيند په اوبو بپتسمه ورکړه.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(23102, 'Mark 1:6', 'Mark', 1, 6, '&nbsp;د يحيىٰ جامې د اوښ د وړۍ وې او د څرمنې پټۍ يې د ملا نه تړلې وه او مُلخان او ځنګلى شات يې خوراک وو.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(23103, 'Mark 1:7', 'Mark', 1, 7, '&nbsp;هغۀ به دا اِعلان کولو چې، ”زما نه پس به هغه څوک راځى چې زما نه ډېر زورَور دے. زۀ د دې جوګه هم نۀ يم چې ټيټ شم او د هغۀ د پېزار تسمې پرانيزم.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(23104, 'Mark 1:8', 'Mark', 1, 8, '&nbsp;ما خو په اوبو ستاسو بپتسمه وکړه خو هغه به تاسو له په روحُ القُدس بپتسمه درکوى.“', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(23105, 'Mark 1:9', 'Mark', 1, 9, '&nbsp;هم په هغه ورځو کښې داسې وشول چې د ګليل د ناصرت نه عيسىٰ راغلو او د اُردن د سيند په اوبو کښې يې د يحيىٰ نه بپتسمه واخسته.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(23106, 'Mark 1:10', 'Mark', 1, 10, '&nbsp;څۀ وخت چې هغه د اوبو نه بهر راووتو نو هغۀ آسمانونه پرانستى وليدل او روحُ القُدس د کونترې په شکل کښې په هغۀ رانازل شو.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(23107, 'Mark 1:11', 'Mark', 1, 11, '&nbsp;او د آسمان نه يو آواز راغلو چې، ”تۀ زما محبوب زوئ يې، ستا نه زۀ راضى يم.“', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(23108, 'Mark 1:12', 'Mark', 1, 12, '&nbsp;سمدستى روحُ القُدس هغه بيابان ته په تلو مجبور کړو.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(23109, 'Mark 1:13', 'Mark', 1, 13, '&nbsp;او هلته کښې هغه تر څلوېښتو ورځو پورې د اِبليس په لمسون کښې وآزمائيلے شو. هغه د ځنګلى ځناورو سره وو او فرښتې د هغۀ په خِدمت کښې حاضرې شوې.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(23110, 'Mark 1:14', 'Mark', 1, 14, '&nbsp;نو هرکله چې يحيىٰ ګرفتار شو نو عيسىٰ ګليل ته راغلو او د خُدائ پاک د زيرى بيان يې کولو چې،', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(23111, 'Mark 1:15', 'Mark', 1, 15, '&nbsp;”وخت پوره شو، د خُدائ پاک بادشاهى ستاسو مينځ ته راغلې ده. توبه ګار شئ او په زېرى ايمان راوړئ.“', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(23112, 'Mark 1:16', 'Mark', 1, 16, '&nbsp;کله چې عيسىٰ د ګليل درياب په غاړه ګرځېدو نو هغۀ دوه وروڼه وليدل چې شمعون او د هغۀ ورور اندرياس وو. هغوئ په درياب کښې جال اچولو ځکه چې هغوئ ماهيګر وُو.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(23113, 'Mark 1:17', 'Mark', 1, 17, '&nbsp;عيسىٰ هغوئ ته وفرمائيل چې، ”ما پسې راځئ او زۀ به تاسو نه آدم‌ګير جوړ کړم.“', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(23114, 'Mark 1:18', 'Mark', 1, 18, '&nbsp;او هغوئ سمدستى خپل جالونه پرېښودل او په هغۀ پسې روان شول.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(23115, 'Mark 1:19', 'Mark', 1, 19, '&nbsp;کله چې عيسىٰ د دې ځائ نه لږ وړاندې لاړو نو هغۀ يعقوب د زبدى زوئ، او د هغۀ ورور يوحنا وليدل، چې په خپله کشتۍ کښې ناست وُو او جالونه يې مرمت کول.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(23116, 'Mark 1:20', 'Mark', 1, 20, '&nbsp;نو سمدستى هغۀ هغوئ راوبلل، او هغوئ خپل پلار زبدى د مزدورانو سره په کشتۍ کښې پرېښودو او په هغۀ پسې روان شول.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(23117, 'Mark 1:21', 'Mark', 1, 21, '&nbsp;بيا دوئ د کفرنحُوم ښاريې ته لاړل نو کله چې د سبت ورځ راغله، عيسىٰ عبادتخانې ته ننوتو او هلته يې تعليم شروع کړو.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(23118, 'Mark 1:22', 'Mark', 1, 22, '&nbsp;نو خلق د هغۀ په تعليم حق حېران شول. ځکه چې هغۀ د هغوئ د شرعې عالمانو په شان نه، خو په پوره اختيار سره يې تعليم ورکولو.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(23119, 'Mark 1:23', 'Mark', 1, 23, '&nbsp;نو بيا په دغه وخت کښې په عبادتخانه کښې يو سړے وو چې پېرى نيولے وو. ناګهانه هغۀ چغې کړې،', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(23120, 'Mark 1:24', 'Mark', 1, 24, '&nbsp;”تۀ زمونږ نه څۀ غواړې اے عيسىٰ ناصرى؟ تۀ راغلې چې مونږ هلاک کړې څۀ؟ زۀ دې پېژنم چې تۀ څوک يې، تۀ د خُدائ پاک قُدوس يې.“', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(23121, 'Mark 1:25', 'Mark', 1, 25, '&nbsp;عيسىٰ هغه ورټلو او ورته يې وفرمائيل چې، ”چپ شه او د دۀ نه راوځه.“', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(23122, 'Mark 1:26', 'Mark', 1, 26, '&nbsp;او پيرى هغه سړے ډېر ولړزولو او په چغه ترې راووتلو.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(23123, 'Mark 1:27', 'Mark', 1, 27, '&nbsp;هغوئ ټول حق حېران شول او د يو بل نه يې تپوس وکړو چې، ”دا لا څۀ دى؟ دا خو د اختيار سره يو نوے تعليم دے. تر دې چې پيريانو ته حُکم کوى، او هغوئ يې هم منى.“', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(23124, 'Mark 1:28', 'Mark', 1, 28, '&nbsp;نو ډېر زر په ټول ګليل کښې هغه مشهور شو.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(23125, 'Mark 1:29', 'Mark', 1, 29, '&nbsp;د عبادتخانې نه په راوتو هغوئ نېغ د شمعون او اندرياس کره لاړل او يعقوب او يوحنا هم ورسره ملګرى وُو.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(23126, 'Mark 1:30', 'Mark', 1, 30, '&nbsp;د شمعون خواښې تبې نيولې وه، او په کټ کښې پرته وه. هغوئ بيا د هغې د بيمارۍ حال ورته ووئيلو.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(23127, 'Mark 1:31', 'Mark', 1, 31, '&nbsp;عيسىٰ ورغلو او د هغې لاس يې ونيولو او په پښو يې ودروله او تبه يې لاړه او هغه د هغوئ په خِدمت کولو شروع شوه.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(23128, 'Mark 1:32', 'Mark', 1, 32, '&nbsp;هغه ماښام د نمر د پرېوتو نه پس هغوئ عيسىٰ له ټول بيماران او پيريانو نيولى خلق راوستل.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(23129, 'Mark 1:33', 'Mark', 1, 33, '&nbsp;او ټوله ښاريه د هغۀ د کور مخې ته راټوله شوله.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(23130, 'Mark 1:34', 'Mark', 1, 34, '&nbsp;عيسىٰ ډېر بيماران روغ کړل چې په مختلفو بيماريانو آخته وُو او ډېر پيريان يې وشړل. هغۀ پيريان د خبرو نه منع کړل ځکه چې هغوئ ته پته وه چې دا څوک دے.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(23131, 'Mark 1:35', 'Mark', 1, 35, '&nbsp;سحر وختى د نمر ختو نه وړاندې عيسىٰ پاڅېدو او بهر لاړو. هغه ځان له يو خوشى بيابان ته لاړو او هلته يې دُعا کوله.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(23132, 'Mark 1:36', 'Mark', 1, 36, '&nbsp;خو شمعون او د هغۀ ملګرو يې تلاش کولو چې وې مومى،', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(23133, 'Mark 1:37', 'Mark', 1, 37, '&nbsp;او کله چې يې وموندلو نو ورته يې ووئيل چې، ”ټول خلق ستا په تلاش کښې دى.“', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(23134, 'Mark 1:38', 'Mark', 1, 38, '&nbsp;هغۀ جواب ورکړو چې، ”راځئ چې نزدې ښارونو ته لاړ شُو چې زۀ هلته هم خپل بيان وکړم ځکه چې زۀ په هم دې غرض راوتلے يم.“', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(23135, 'Mark 1:39', 'Mark', 1, 39, '&nbsp;نو هغه په ټول ګليل کښې ګرځېدو، د هغوئ په عبادتخانو کښې يې بيان کولو او پيريان يې شړل.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(23136, 'Mark 1:40', 'Mark', 1, 40, '&nbsp;عيسىٰ له يو جذامى راغلو، مِنت زارى يې ورته وکړل او ورته په سجده پرېوتو، عيسىٰ ته يې ووئيل چې، ”کۀ تۀ وغواړې نو ما روغولے شې.“', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(23137, 'Mark 1:41', 'Mark', 1, 41, '&nbsp;د عيسىٰ زړۀ په هغۀ وسوزېدلو، خپل لاس يې وراوږد کړو، او د هغۀ سره يې ولګولو او ورته يې فرمائيل چې، ”آو، زۀ غواړم. پاک شه.“', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(23138, 'Mark 1:42', 'Mark', 1, 42, '&nbsp;نو سمدستى د هغۀ نه جذام ختم شو او هغه پاک شو.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(23139, 'Mark 1:43', 'Mark', 1, 43, '&nbsp;بيا عيسىٰ هغه د دې سخت حکم سره رُخصت کړو،', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(23140, 'Mark 1:44', 'Mark', 1, 44, '&nbsp;”ګوره چې هيچا ته د دې په حقله څۀ ونۀ وائې. لاړ شه، خپل ځان اِمام ته وښايه او کومه شکرانه چې موسىٰ مقرره کړې ده هغه ورکړه. دا به ستا د روغولو ګواهى شى.“', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(23141, 'Mark 1:45', 'Mark', 1, 45, '&nbsp;خو هغه سړے بهر لاړو او د دې قيصې نه يې ټول خلق خبر کړل. دا خبره يې تر لرې لرې خوره کړله تر دې چې عيسىٰ به يو ښار ته هم په ښکاره نۀ شو تلے او بهر به په خوشو ځايونو کښې پاتې کېدو. خو بيا به هم خلق د هر لورى نه هغۀ له راتلل.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(23142, 'Mark 2:1', 'Mark', 2, 1, '&nbsp;کله چې عيسىٰ يو څو ورځې وروستو کفرنحُوم ته واپس شو نو خلقو ته دا پته ولګېده چې هغه په کور کښې دے.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(23143, 'Mark 2:2', 'Mark', 2, 2, '&nbsp;او دومره ډېر خلق ورته راټول شول چې د دروازې نه بهر هم نۀ ځائېدل. او څۀ وخت چې هغۀ هغوئ ته کلام بيانولو،', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(23144, 'Mark 2:3', 'Mark', 2, 3, '&nbsp;نو څلورو کسانو يو شل سړے راوچت کړے وو او هغۀ له يې په پوزى کښې راوړو.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(23145, 'Mark 2:4', 'Mark', 2, 4, '&nbsp;خو د ګڼې له کبله يې هغۀ ته نزدې نۀ کړے شو، نو هغوئ د کوټې چت په هغه ځائ کښې سورے کړو چرته چې عيسىٰ وو او په هغه سورې کښې يې هغه شل سړے په بستره کښې د هغۀ مخې ته ورښکته کړو.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(23146, 'Mark 2:5', 'Mark', 2, 5, '&nbsp;کله چې عيسىٰ د هغوئ دا ايمان وليدو نو هغه شل سړى ته يې وفرمائيل، ”زما زويه، ستا ګناهونه معاف شول.“', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(23147, 'Mark 2:6', 'Mark', 2, 6, '&nbsp;خو هلته په دغه موقع يو څو د شرعې عالمان ناست وُو، هغوئ د ځان سره ووئيل چې،', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(23148, 'Mark 2:7', 'Mark', 2, 7, '&nbsp;”دا سړے داسې خبرې ولې کوى؟ دا خو کُفر دے. د خُدائ پاک نه علاوه هم لا څوک د چا ګناهونه بخښلے شى څۀ؟“', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(23149, 'Mark 2:8', 'Mark', 2, 8, '&nbsp;سمدستى عيسىٰ پوهه شو چې دوئ په زړۀ کښې څۀ سوچ کوى نو هغوئ ته يې وفرمائيل چې، ”تاسو په خپلو زړونو کښې داسې سوالونه ولې راولئ؟', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(23150, 'Mark 2:9', 'Mark', 2, 9, '&nbsp;آيا دا آسانه خبره ده چې زۀ دې شل کس ته ووايم چې ګناهونه دې معاف شُو، او کۀ دا ووايم چې پاڅه خپله بستره دې واخله او وګرځه؟', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(23151, 'Mark 2:10', 'Mark', 2, 10, '&nbsp;خو دا ځکه چې تاسو په دې پوهه شئ چې اِبن آدم سره په دُنيا کښې د ګناهونو د بخښلو اختيار هم شته،“ نو هغه شل سړى ته يې وفرمائيل چې،', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(23152, 'Mark 2:11', 'Mark', 2, 11, '&nbsp;”زۀ تا ته وايم چې، پاڅه، خپله بستره دې واخله او کور ته ځه.“', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(23153, 'Mark 2:12', 'Mark', 2, 12, '&nbsp;او هغه پاڅېدو، سمدستى يې خپله بستره واخسته او د ټولو په مخکښې روان شو. دغه شان هغوئ ټول حېران پاتې شول او د خُدائ پاک ثناء يې ووئيله. هغوئ ووئيل چې، ”داسې کار خو مونږ چرې هم نۀ وو ليدلے.“', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(23154, 'Mark 2:13', 'Mark', 2, 13, '&nbsp;عيسىٰ يو ځل بيا د درياب غاړې ته لاړو، ګڼ خلق ورله راغلل او هغۀ هلته ورته تعليم ورکړو.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(23155, 'Mark 2:14', 'Mark', 2, 14, '&nbsp;څنګه چې هغه له دې ځايه لاړو هغۀ د حلفۍ زوئ ليوى د محصُول په کُرسۍ ناست وليدو او هغۀ ته يې وفرمائيل چې، ”ما پسې راځه.“ ليوى پاڅېدو او په هغۀ پسې روان شو.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(23156, 'Mark 2:15', 'Mark', 2, 15, '&nbsp;نو څۀ وخت وروستو چې عيسىٰ د ليوى په کور کښې روټۍ ته کښېناستو، ډېر محصولچيان، ګناهګاران او د هغۀ مريدان ورسره يو ځائ روټۍ ته ناست وُو، ځکه چې ډېرو خلقو هغه منلو.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(23157, 'Mark 2:16', 'Mark', 2, 16, '&nbsp;ځينو فريسيانو، څوک چې د شرعې عالمان وُو چې دا وليدل چې هغه د محصولچيانو او ګناهګارانو په دې ډله کښې روټۍ ته ناست دے، نو د هغۀ مريدانو ته يې ووئيل چې، ”هغه ولې د محصولچيانو او ګناهګارو سره يو ځائ روټۍ خورى؟“', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(23158, 'Mark 2:17', 'Mark', 2, 17, '&nbsp;چې عيسىٰ دا خبره واورېدله نو دوئ ته يې وفرمائيل چې، ”روغو خلقو ته د طبيب حاجت نۀ وى خو بيمارانو ته يې وى. زۀ د دې دپاره نۀ يم راغلے چې صادقانو له دعوت ورکړم بلکې ګناهګارانو له.“', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(23159, 'Mark 2:18', 'Mark', 2, 18, '&nbsp;يو ځلې چې د يحيىٰ د مريدانو او د فريسيانو روژه وه نو ځينې خلق ورله راغلل او وې وئيل چې، ”څۀ وجه ده چې د يحيىٰ مريدان او د فريسيانو مريدان خو روژه نيسى، ولې ستا مريدان يې نۀ نيسى؟“', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(23160, 'Mark 2:19', 'Mark', 2, 19, '&nbsp;عيسىٰ هغوئ ته وفرمائيل، ”کله چې د وادۀ زلمے د جنجيانو سره وى نو هغوئ روژه نيولے شى څۀ؟ ترڅو پورې چې د وادۀ زلمے د دوئ سره وى نو دوئ به روژه نۀ نيسى.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(23161, 'Mark 2:20', 'Mark', 2, 20, '&nbsp;يو وخت به راشى چې د وادۀ زلمے به د دوئ نه جدا کړے شى او په هغه ورځ به دوئ روژه نيسى.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(23162, 'Mark 2:21', 'Mark', 2, 21, '&nbsp;هيڅوک هم نوے پيوند په زړه چُوغه باندې نۀ لګوى، او کۀ څوک داسې کوى نو دا پيوند به چُوغه نوره هم وشلوى او نور لوئ سورے به په کښې جوړ شى.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(23163, 'Mark 2:22', 'Mark', 2, 22, '&nbsp;هيڅوک هم نوى مے په زړو مشکونو کښې نۀ اچوى، ګنې نو مے به مشکونه وشلوى، مے او مشکونه دواړه به ضائع شى. خو هر څوک نوى مے په نوؤ مشکونو کښې اچوى.“', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(23164, 'Mark 2:23', 'Mark', 2, 23, '&nbsp;د يو سبت په ورځ عيسىٰ د فصل په پټو تېرېدو نو په تلو تلو کښې د هغۀ مريدانو وَږى راوشوکول.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(23165, 'Mark 2:24', 'Mark', 2, 24, '&nbsp;فريسيانو هغۀ ته ووئيل چې، ”وګوره، کوم کار چې د سبت په ورځ ناروا وى، دوئ ولې هغه کوى؟“', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(23166, 'Mark 2:25', 'Mark', 2, 25, '&nbsp;هغۀ ورته جواب ورکړو چې، ”تاسو چرې دا نۀ دى لوستلى کله چې داؤد او د هغۀ دوستان اوږى شوى وُو او د خوراک دپاره هيڅ ورسره نۀ وُو نو څۀ يې وکړل؟', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(23167, 'Mark 2:26', 'Mark', 2, 26, '&nbsp;هغه د خُدائ پاک کور ته ننوتو کله چې ابياتار مشر اِمام وو او پېش کړے شوې روټۍ يې وخوړه اګر چې هغه په دۀ او د دۀ په ملګرو ناروا وه او صرف اِمامانو ته روا وه. او هغۀ څۀ خپلو دوستانو ته هم ورکړه.“', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(23168, 'Mark 2:27', 'Mark', 2, 27, '&nbsp;عيسىٰ ورته دا هم وفرمائيل چې، ”سبت د بنى آدم دپاره جوړ شوے دے، نه چې بنى آدم د سبت دپاره.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
