(23171, 'Mark 3:2', 'Mark', 3, 2, '&nbsp;او هغوئ دې ته کتل چې عيسىٰ به د سبت په ورځ هغه روغ کړى او کۀ نه، ځکه چې هغوئ به د هغۀ خلاف اِلزام لګولو ته تيار ناست وُو.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
